import{d as s,c as r,a as e,k as t,l as i,m as n,p as l,o as c,h as d}from"./index-DNKBB5nh.js";const m={class:"min-h-screen bg-gray-50 py-12 px-4 sm:px-6 lg:px-8"},u={class:"max-w-4xl mx-auto bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden"},p={class:"px-6 py-8 md:p-12"},g={class:"mt-12 pt-8 border-t text-center"},v=s({__name:"PrivacyPolicyView",setup(x){return(b,o)=>{const a=l("router-link");return c(),r("div",m,[e("div",u,[e("div",p,[o[1]||(o[1]=t('<h1 class="text-3xl md:text-4xl font-bold text-gray-900 mb-6 border-b pb-6">Privacidad y condiciones</h1><p class="mb-8 text-gray-600 text-lg leading-relaxed"> Esta política de privacidad rige para todas las aplicaciones móviles para Android creadas por TecnoWorld y publicadas en la cuenta de desarrollador con el nombre antes mencionado. </p><h2 class="text-2xl font-semibold text-gray-800 mt-10 mb-5">¿Que tipo de información recolectamos?</h2><p class="mb-6 text-gray-700 leading-relaxed"> Para el correcto funcionamiento de las aplicaciones que construimos o desarrollamos, estos son algunos de los datos que recolectamos: </p><h3 class="text-xl font-medium text-gray-800 mt-8 mb-3">Ubicación</h3><p class="mb-6 text-gray-700 leading-relaxed"> Para el caso de las aplicaciones que sea necesario accedemos a los datos proporcionados por el GPS. Estos datos no los manejamos nosotros, son directamente manejado por <a href="https://maps.google.com" target="_blank" rel="noopener noreferrer" class="text-blue-600 hover:text-blue-800 transition-colors underline decoration-blue-300 underline-offset-2">Google Maps</a> (nuestro proveedor de mapas). </p><h3 class="text-xl font-medium text-gray-800 mt-8 mb-3">Datos de Registro</h3><p class="mb-6 text-gray-700 leading-relaxed"> Quiero informarle que cada vez que utiliza mi Servicio, en caso de un error en la aplicación, recopilo datos e información (a través de productos de terceros) en su teléfono llamados Datos de registro. Estos datos de registro pueden incluir información como la dirección del Protocolo de Internet («IP») de su dispositivo, el nombre del dispositivo, la versión del sistema operativo, la configuración de la aplicación cuando utiliza mi Servicio, la hora y la fecha de uso del Servicio y otras estadísticas. </p><h3 class="text-xl font-medium text-gray-800 mt-8 mb-3">Cookies y Sesiones</h3><p class="mb-6 text-gray-700 leading-relaxed"> Las cookies y sesiones son archivos con una pequeña cantidad de datos que se usa comúnmente como identificadores únicos anónimos. Esto se envian a su navegador desde los sitios web que visita y se almacenan en la memoria interna de su dispositivo. Este servicio no utiliza estas cookies explícitamente. sin embargo las aplicaciones utilizan almacenamiento en cache para guadar las sessiones, como tambien las aplicaciones pueden usar código de terceros y bibliotecas que usan cookies, cache de almacenamiento para recopilar informacion y mejorar sus servicios. Tiene la opción de aceptar o rechazar nuestras sesiones, es posible que no pueda usar algunas partes de este Servicio. </p><h3 class="text-xl font-medium text-gray-800 mt-8 mb-4">Proveedores de servicio</h3><p class="mb-3 text-gray-700 leading-relaxed">Podemos emplear a empresas o individuos de terceros debido a las siguientes razones:</p><ul class="list-disc pl-6 mb-6 text-gray-700 space-y-2 marker:text-gray-400"><li>Para facilitar nuestros servicios;</li><li>Para proporcionar el Servicio en nuestro nombre;</li><li>Para realizar servicios relacionados con el Servicio; o</li><li>Para ayudar a analizar cómo se utiliza nuestro Servicio</li></ul><p class="mb-6 text-gray-700 leading-relaxed"> Deseo informar a los usuarios de este Servicio que estos terceros tienen acceso a su Información personal. La razón es realizar las tareas que se les asignaron en nuestro nombre. Sin embargo, están obligados a no divulgar ni utilizar la información para ningún otro propósito. </p><h3 class="text-xl font-medium text-gray-800 mt-8 mb-3">Seguridad</h3><p class="mb-6 text-gray-700 leading-relaxed"> Valoro su confianza en proporcionarnos su información personal, por lo tanto nos esforzamos por utilizar medios comercialmente aceptables para protegerla. Pero recuerde que ningún método de transmisión por internet o método de almacenamiento eletrónico es 100% seguro y confiable, y no puedo garantizar su seguridad absoluta. </p><h3 class="text-xl font-medium text-gray-800 mt-8 mb-3">Enlaces a otros sitios</h3><p class="mb-6 text-gray-700 leading-relaxed"> Este servicios puede contener enlaces a otros sitios. Si hace click en un enlace de un tercero, será dirigido a ese sitio. Tenga en cuenta que estos sitios externos no son operados por nuestros servisios. Por lo tanto, le recomiendo que revise la Política de privacidad de estos sitios web. No tenemos control ni asumimos ninguna responsabilidad por el contenido, la política de privacidad o las prácticas de sitios o servicios de tercero. </p><h3 class="text-xl font-medium text-gray-800 mt-8 mb-3">Privacidad de los menores de edad</h3><p class="mb-6 text-gray-700 leading-relaxed"> Estos Servicios no se dirigen a ninguna persona menor de 13 años. No recopilo a sabiendas información de identificación personal de niños menores de 13 años. En el caso de que descubra que un niño menor de 13 años me ha proporcionado información personal, la borro inmediatamente de nuestros servidores. Si usted es padre o tutor y sabe que su hijo nos ha proporcionado información personal, comuníquese conmigo para que pueda realizar las acciones necesarias. </p><h2 class="text-2xl font-semibold text-gray-800 mt-10 mb-5">¿Que hacemos con los datos que recolectamos?</h2><p class="mb-3 text-gray-700 leading-relaxed">Los datos recolectados son de dos tipos:</p><ol class="list-decimal pl-6 mb-6 text-gray-700 space-y-2 marker:text-gray-500 font-medium"><li>Datos recolectado por nosotros.</li><li>Datos recolectado por terceros.</li></ol><h3 class="text-xl font-medium text-gray-800 mt-8 mb-3">Datos recolectados por nosotros</h3><p class="mb-6 text-gray-700 leading-relaxed"> Estos datos se recolectan para obtener un feedback de que es lo que quieren nuestros usuarios y así poder mejorar brindando las correctas mejoras en cada actualización. Los datos son manipulados a nivel de código, luego procesados en grandes cantidades, pero en ningún momento accedemos a datos de un usuario en particular, pues están encriptados y solo el usuario dueño de la información puede acceder a ellos. </p><h3 class="text-xl font-medium text-gray-800 mt-8 mb-4">Datos recolectados por terceros</h3><p class="mb-3 text-gray-700 leading-relaxed">En los datos recolectados por terceros están:</p><ul class="list-disc pl-6 mb-6 text-gray-700 space-y-2 marker:text-gray-400"><li><a href="https://play.google.com/store" target="_blank" rel="noopener noreferrer" class="text-blue-600 hover:text-blue-800 transition-colors underline decoration-blue-300 underline-offset-2">Google Play</a></li><li><a href="https://firebase.google.com" target="_blank" rel="noopener noreferrer" class="text-blue-600 hover:text-blue-800 transition-colors underline decoration-blue-300 underline-offset-2">Firebase</a></li></ul>',28)),e("div",g,[i(a,{to:"/",class:"inline-flex items-center text-blue-600 hover:text-blue-800 font-medium"},{default:n(()=>[...o[0]||(o[0]=[e("svg",{xmlns:"http://www.w3.org/2000/svg",class:"h-5 w-5 mr-1",viewBox:"0 0 20 20",fill:"currentColor"},[e("path",{"fill-rule":"evenodd",d:"M9.707 16.707a1 1 0 01-1.414 0l-6-6a1 1 0 010-1.414l6-6a1 1 0 011.414 1.414L5.414 9H17a1 1 0 110 2H5.414l4.293 4.293a1 1 0 010 1.414z","clip-rule":"evenodd"})],-1),d(" Volver al inicio ",-1)])]),_:1})])])])])}}});export{v as default};
